/* ФИНАНСОВЫЕ КАЛЬКУЛЯТОРЫ: пени по доле ключевой ставки, проценты по ст. 395 ГК РФ,
   график кредита (аннуитет и дифференцированный, досрочные погашения), вклад
   с капитализацией и НДС. Расчёт ложится на лист от выделенной клетки — формулами,
   чтобы было видно, как посчитано, и можно было поправить.
   История ключевой ставки Банка России — внутри плагина (дата актуальности — ниже). */

/* ===== Поле на клетках листа: общий кусок игр магазина =====
   Строки и столбцы здесь — С НУЛЯ (r, c); адреса A1 считаются отсюда же.
   ячейка(строка, столбец) API плагина считает с единицы — поэтому везде «+ 1». */
const БУКВА = c => { let s = '', n = c + 1; while(n > 0){ const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = (n - 1 - m) / 26; } return s; };
const АДРЕС = (r, c) => БУКВА(c) + (r + 1);
const ОБЛАСТЬ = (r1, c1, r2, c2) => АДРЕС(r1, c1) + ':' + АДРЕС(r2, c2);
const клетка = (r, c) => ячейка(r + 1, c + 1);
/* Квадратные клетки: ширина столбца в знаках (знак — 7 точек), высота строки в пунктах (×4/3 точки). */
function клеткиКвадратом(r1, c1, r2, c2, точек){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(точек / 7);
  о.SetRowHeight(точек * 0.75);
}
/* Вернуть области обычные размеры клеток (столбец 92 точки, строка 24 точки = 18 пунктов). */
function обычныеРазмеры(r1, c1, r2, c2){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(92 / 7);
  о.SetRowHeight(18);
}
/* Ширина одного столбца и высота одной строки в точках экрана. */
function ширинаСтолбца(c, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(0, c, 0, c)).SetColumnWidth(точек / 7); }
function высотаСтроки(r, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r, 0, r, 0)).SetRowHeight(точек * 0.75); }
/* Приложение запоминает смещения строк и не сбрасывает их, когда плагин меняет высоты строк:
   после этого щелчок мыши попадает не в ту клетку. Пустая запись в далёкую пустую строку
   растит сетку листа, и смещения пересчитываются. Звать после смены высот. */
async function обновитьВысоты(){
  /* каждый раз — строка дальше прежней: сетка растёт, только если запись за её краем */
  let n = 0; try { n = +лист().память('высоты-шаг') || 0; } catch(e){}
  for(let k = n + 1; k <= n + 40; k++){
    const r = 5999 + k;
    let v = null;
    try { v = await клетка(r, 0).прочитать(); } catch(e){ continue; }
    if(v === null || v === undefined || v === ''){
      клетка(r, 0).значение = null;
      try { лист().запомнить('высоты-шаг', k); } catch(e){}
      return true;
    }
  }
  return false;
}
/* Курсор — на «стоянку» рядом с полем. Тогда повторный щелчок по той же клетке
   снова сменит выделение, и плагин получит событие: иначе второй щелчок молчал бы. */
function наСтоянку(r, c){ клетка(r, c).выделить(); }
/* Пуста ли область листа: игра не должна молча затирать чужие данные. */
async function областьПуста(r1, c1, r2, c2){
  const строки = await диапазон(ОБЛАСТЬ(r1, c1, r2, c2)).прочитать();
  for(const ряд of строки || []) for(const v of ряд || []) if(v !== null && v !== undefined && v !== '') return false;
  return true;
}
/* Рамка: все четыре стороны одним видом. */
const РАМКА = (вид, цвет) => ({в: {вид, цвет}, н: {вид, цвет}, л: {вид, цвет}, п: {вид, цвет}});
/* Число со словом в нужной форме: число(5, 'выстрел', 'выстрела', 'выстрелов') → «5 выстрелов». */
function число(n, одна, две, пять){ const a = Math.abs(n) % 100, b = a % 10;
  return n + ' ' + (a > 10 && a < 20 ? пять : b === 1 ? одна : b >= 2 && b <= 4 ? две : пять); }
/* Время «м:сс». */
const ВРЕМЯ = с => Math.floor(с / 60) + ':' + String(Math.floor(с % 60)).padStart(2, '0');
/* Повод события — клетка с нуля и на нужном ли листе. */
function гдеЩелчок(п, лист){
  if(!п || !п.адрес || (лист && п.лист !== лист)) return null;
  if(п.клеток > 1) return null;                     /* протянули мышью область — это не ход */
  return {r: п.строка - 1, c: п.столбец - 1};
}
/* Защита от «правой кнопки»: правый щелчок сначала зовёт меню, а через 150 мс
   приходит выделение той же клетки. Такой выбор ходом не считаем. */
let последнееМеню = {адрес: '', t: 0};
const этоПослеМеню = п => п && п.адрес === последнееМеню.адрес && Date.now() - последнееМеню.t < 1500;
/* ===== конец общего куска ===== */
/* Оформление области по клеткам. Api GetRange(…).SetNumberFormat и другие оформления области из потока
   задевают только ту часть, что была занята при запуске потока, — свежие строки остаются без оформления.
   л — лист плагина: лист(имя) или черновик; строки и столбцы — с нуля. */
function оформитьОбласть(л, r1, c1, r2, c2, стиль){
  if((r2 - r1 + 1) * (c2 - c1 + 1) > 300000) return false;
  for(let r = r1; r <= r2; r++) for(let c = c1; c <= c2; c++) л.ячейка(r + 1, c + 1).стиль = стиль;
  return true;
}

const СТАВКИ_НА = '04.10.2026';
/* Ключевая ставка Банка России: дата, с которой действует, и ставка, % годовых. */
const КЛЮЧЕВАЯ = [['13.09.2013', 5.5], ['03.03.2014', 7], ['28.04.2014', 7.5], ['28.07.2014', 8], ['05.11.2014', 9.5], ['12.12.2014', 10.5],
  ['16.12.2014', 17], ['02.02.2015', 15], ['16.03.2015', 14], ['05.05.2015', 12.5], ['16.06.2015', 11.5], ['03.08.2015', 11], ['14.06.2016', 10.5],
  ['19.09.2016', 10], ['27.03.2017', 9.75], ['02.05.2017', 9.25], ['19.06.2017', 9], ['18.09.2017', 8.5], ['30.10.2017', 8.25], ['18.12.2017', 7.75],
  ['12.02.2018', 7.5], ['26.03.2018', 7.25], ['17.09.2018', 7.5], ['17.12.2018', 7.75], ['17.06.2019', 7.5], ['29.07.2019', 7.25], ['09.09.2019', 7],
  ['28.10.2019', 6.5], ['16.12.2019', 6.25], ['10.02.2020', 6], ['27.04.2020', 5.5], ['22.06.2020', 4.5], ['27.07.2020', 4.25], ['22.03.2021', 4.5],
  ['26.04.2021', 5], ['15.06.2021', 5.5], ['26.07.2021', 6.5], ['13.09.2021', 6.75], ['25.10.2021', 7.5], ['20.12.2021', 8.5], ['14.02.2022', 9.5],
  ['28.02.2022', 20], ['11.04.2022', 17], ['04.05.2022', 14], ['27.05.2022', 11], ['14.06.2022', 9.5], ['25.07.2022', 8], ['19.09.2022', 7.5],
  ['24.07.2023', 8.5], ['15.08.2023', 12], ['18.09.2023', 13], ['30.10.2023', 15], ['18.12.2023', 16], ['29.07.2024', 18], ['16.09.2024', 19],
  ['28.10.2024', 21], ['09.06.2025', 20], ['28.07.2025', 18], ['15.09.2025', 17], ['27.10.2025', 16.5], ['22.12.2025', 16], ['16.02.2026', 15.5],
  ['23.03.2026', 15], ['27.04.2026', 14.5], ['22.06.2026', 14.25], ['27.07.2026', 14]];
const МОРАТОРИЙ_2022 = ['01.04.2022', '01.10.2022'];

/* --- даты: число дней, как их хранит таблица (1 = 31.12.1899) --- */
const ДЕНЬ = 86400000, НОЛЬ = Date.UTC(1899, 11, 30);
const деньИз = (y, m, d) => Math.round((Date.UTC(y, m - 1, d) - НОЛЬ) / ДЕНЬ);
function разобратьДату(s){
  s = String(s == null ? '' : s).trim();
  let m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s);
  if(m) return деньИз(+m[1], +m[2], +m[3]);
  m = /^(\d{1,2})\.(\d{1,2})\.(\d{4})$/.exec(s);
  if(m) return деньИз(+m[3], +m[2], +m[1]);
  return null;
}
const ДМГ = д => { const x = new Date(НОЛЬ + д * ДЕНЬ); return String(x.getUTCDate()).padStart(2, '0') + '.' + String(x.getUTCMonth() + 1).padStart(2, '0') + '.' + x.getUTCFullYear(); };
const годДня = д => new Date(НОЛЬ + д * ДЕНЬ).getUTCFullYear();
const днейВГоду = y => (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0 ? 366 : 365;
const КЛЮЧ = КЛЮЧЕВАЯ.map(([д, с]) => [разобратьДату(д), с]);
function ключеваяНа(д){ let с = null; for(const [от, x] of КЛЮЧ) if(от <= д) с = x; return с; }
/* сумма с копейками в тексте */
const руб = x => (Math.round(x * 100) / 100).toLocaleString('ru-RU', {minimumFractionDigits: 2, maximumFractionDigits: 2}) + ' ₽';
const ДЕНЬГИ = '#,##0.00 ₽', ДАТА = 'dd.mm.yyyy';
const ЗАГ = {b: 1, fill: '#eef3fe', гр: РАМКА('тонкая', '#9aa4b5'), wrap: 1, valign: 'middle', align: 'center'};
const ЯЧ = {гр: РАМКА('тонкая', '#c5ccd8')};

/* платежи из многострочного поля: «дд.мм.гггг сумма» в строке */
function платежи(текст){
  const out = [], плохие = [];
  for(const строка of String(текст || '').split(/\n/)){
    const s = строка.trim(); if(!s) continue;
    const m = /^(\S+)\s+([\d\s.,]+)\s*(.*)$/.exec(s);
    const д = m && разобратьДату(m[1]), сумма = m && parseFloat(m[2].replace(/\s/g, '').replace(',', '.'));
    if(д === null || !m || !(сумма > 0)){ плохие.push(s); continue; }
    out.push({д, сумма, ещё: (m[3] || '').trim().toLowerCase()});
  }
  return {список: out.sort((a, b) => a.д - b.д), плохие};
}

/* --- куда писать: от выделенной клетки; занято — спросить --- */
async function начало(ширина, высота){
  const в = книга.выделение || {r1: 1, c1: 1};
  const r = в.r1 - 1, c = в.c1 - 1;
  if(!(await областьПуста(r, c, r + высота - 1, c + ширина - 1))){
    if(!(await диалог.вопрос('Расчёт займёт ' + ОБЛАСТЬ(r, c, r + высота - 1, c + ширина - 1) + ', а там уже что-то есть. Записать поверх? (Лучше — щёлкнуть пустую клетку или завести пустой лист.)'))) return null;
  }
  return {r, c};
}
function пиши(r, c, v, стиль){ const к = клетка(r, c); к.значение = v; if(стиль) к.стиль = стиль; return к; }
function формула(r, c, ф, стиль){ const к = клетка(r, c); к.формула = ф; if(стиль) к.стиль = стиль; return к; }

/* ================= ПЕНИ И СТ. 395 ГК ================= */
/* Разбивка просрочки на периоды: меняются ставка, долг (после частичной оплаты), год (для 395)
   или доля (с 31-го дня). Мораторий — отдельный период без начисления. */
function разбить(о){
  const точки = new Set([о.с, о.по + 1]);
  if(о.ставка === 'периоды') for(const [д] of КЛЮЧ) if(д > о.с && д <= о.по) точки.add(д);
  if(о.год) for(let y = годДня(о.с) + 1; y <= годДня(о.по); y++) точки.add(деньИз(y, 1, 1));
  for(const п of о.оплаты) if(п.д >= о.с && п.д < о.по) точки.add(п.д + 1);
  if(о.с31) { const д = о.с + 30; if(д > о.с && д <= о.по) точки.add(д); }
  if(о.мораторий){ const [a, b] = МОРАТОРИЙ_2022.map(разобратьДату); if(a > о.с && a <= о.по) точки.add(a); if(b + 1 > о.с && b + 1 <= о.по) точки.add(b + 1); }
  let т = [...точки].sort((a, b) => a - b);
  if(о.мораторий){ const [ma, mb] = МОРАТОРИЙ_2022.map(разобратьДату); т = т.filter(x => !(x > ma && x <= mb)); }
  const out = [];
  let долг = о.долг;
  for(let i = 0; i < т.length - 1; i++){
    const a = т[i], b = т[i + 1] - 1;
    долг = о.долг - о.оплаты.filter(п => п.д < a).reduce((s, п) => s + п.сумма, 0);
    if(долг <= 0.004) break;
    const [ma, mb] = МОРАТОРИЙ_2022.map(разобратьДату);
    const мор = о.мораторий && a >= ma && b <= mb;
    const ставка = о.ставка === 'периоды' ? ключеваяНа(a) : о.ставка === 'дата' ? ключеваяНа(о.по) : о.своя;
    const делитель = о.год ? днейВГоду(годДня(a)) : (о.с31 && a >= о.с + 30 ? 150 : о.делитель);
    const заметки = [];
    if(i === 0) заметки.push('начало просрочки');
    const оплата = о.оплаты.filter(п => п.д === a - 1);
    if(оплата.length) заметки.push('после оплаты ' + оплата.map(п => руб(п.сумма)).join(' + ') + ' ' + ДМГ(оплата[0].д));
    if(о.ставка === 'периоды' && КЛЮЧ.some(([д]) => д === a) && i > 0) заметки.push('ставка ЦБ изменилась');
    if(о.с31 && a === о.с + 30) заметки.push('с 31-го дня — 1/150');
    if(мор) заметки.push('мораторий (постановление Правительства РФ № 497) — не начисляется');
    out.push({a, b, долг, ставка, делитель, мор, заметка: заметки.join('; ')});
  }
  return out;
}
async function разложитьПени(о, заголовок, правило){
  const ряды = разбить(о);
  if(!ряды.length){ панель.сообщение('Нечего считать: долг погашен до начала просрочки.'); return; }
  const высота = 8 + ряды.length + 3;
  const м = await начало(8, высота);
  if(!м) return;
  const {r, c} = м;
  пиши(r, c, заголовок, {b: 1, size: 12});
  пиши(r + 1, c, 'Долг'); пиши(r + 1, c + 1, о.долг, {fmt: ДЕНЬГИ});
  пиши(r + 2, c, 'Просрочка с'); пиши(r + 2, c + 1, о.с, {fmt: ДАТА});
  пиши(r + 3, c, 'Оплата'); пиши(r + 3, c + 1, о.по, {fmt: ДАТА});
  пиши(r + 4, c, правило, {i: 1, color: '#5b6b86'});
  пиши(r + 5, c, 'Ключевая ставка — по данным Банка России на ' + СТАВКИ_НА + '. Расчёт справочный, не юридическая консультация.', {i: 1, color: '#5b6b86', size: 9});
  const h = r + 7;
  ['С', 'По', 'Дней', 'Задолженность', 'Ставка, %', о.год ? 'Дней в году' : 'Доля 1/…', о.год ? 'Проценты' : 'Пени', 'Примечание'].forEach((т, k) => пиши(h, c + k, т, ЗАГ));
  const К = k => БУКВА(c + k);
  ряды.forEach((x, i) => {
    const rr = h + 1 + i, n = rr + 1;
    пиши(rr, c, x.a, Object.assign({fmt: ДАТА}, ЯЧ));
    пиши(rr, c + 1, x.b, Object.assign({fmt: ДАТА}, ЯЧ));
    формула(rr, c + 2, К(1) + n + '-' + К(0) + n + '+1', ЯЧ);
    пиши(rr, c + 3, Math.round(x.долг * 100) / 100, Object.assign({fmt: ДЕНЬГИ}, ЯЧ));
    пиши(rr, c + 4, x.ставка, ЯЧ);
    пиши(rr, c + 5, x.делитель, ЯЧ);
    if(x.мор) пиши(rr, c + 6, 0, Object.assign({fmt: ДЕНЬГИ}, ЯЧ));
    else формула(rr, c + 6, 'ОКРУГЛ(' + К(3) + n + '*' + К(2) + n + '*' + К(4) + n + '/100/' + К(5) + n + ';2)', Object.assign({fmt: ДЕНЬГИ}, ЯЧ));
    пиши(rr, c + 7, x.заметка, {color: '#5b6b86', size: 9});
  });
  const ит = h + 1 + ряды.length;
  пиши(ит, c + 5, 'Итого', {b: 1, align: 'right'});
  формула(ит, c + 6, 'СУММ(' + К(6) + (h + 2) + ':' + К(6) + ит + ')', {b: 1, fmt: ДЕНЬГИ});
  /* для сообщения считаем то же самое сами */
  const итог = ряды.reduce((s, x) => s + (x.мор ? 0 : Math.round(x.долг * (x.b - x.a + 1) * x.ставка / 100 / x.делитель * 100) / 100), 0);
  const ширины = [11, 11, 7, 15, 9, 10, 14, 40];
  ширины.forEach((ш, k) => Api.GetActiveSheet().GetRange(ОБЛАСТЬ(0, c + k, 0, c + k)).SetColumnWidth(ш));
  return {итог, периодов: ряды.length, адрес: АДРЕС(ит, c + 6)};
}
function общееПени(п, преф){
  const долг = +п[преф + 'Долг'], с = разобратьДату(п[преф + 'С']), по = разобратьДату(п[преф + 'По']);
  if(!(долг > 0)) return {ошибка: 'Укажите сумму долга.'};
  if(с === null || по === null) return {ошибка: 'Укажите даты: первый день просрочки и дату оплаты.'};
  if(по < с) return {ошибка: 'Дата оплаты раньше начала просрочки.'};
  const пл = платежи(п[преф + 'Оплаты']);
  if(пл.плохие.length) return {ошибка: 'Не понял строки оплат: ' + пл.плохие.slice(0, 3).join('; ') + '. Формат: 15.03.2025 50000'};
  return {долг, с, по, оплаты: пл.список};
}
async function Пени(){
  const п = параметры({});
  const о = общееПени(п, 'п');
  if(о.ошибка){ панель.сообщение(о.ошибка); return; }
  const доля = String(п.доля || '1/300');
  о.с31 = доля.includes('с 31');
  о.делитель = о.с31 ? 300 : +(доля.match(/1\/(\d+)/) || [0, 300])[1];
  о.ставка = п.ставкаПени === 'своя ставка' ? 'своя' : п.ставкаПени === 'ключевая на дату оплаты' ? 'дата' : 'периоды';
  о.своя = +п.своя || 0;
  if(о.ставка === 'своя' && !(о.своя > 0)){ панель.сообщение('Укажите свою ставку, % годовых.'); return; }
  if(о.ставка !== 'своя' && о.с < КЛЮЧ[0][0]){ панель.сообщение('Ключевая ставка действует с 13.09.2013 — для более ранней даты выберите «своя ставка».'); return; }
  о.мораторий = !!п.пМораторий;
  const правило = 'Пени: ' + доля + ' ' + (о.ставка === 'своя' ? 'ставки ' + о.своя + '% годовых' : 'ключевой ставки ' + (о.ставка === 'дата' ? 'на дату оплаты' : 'по периодам её действия'))
