/* ================= КРЕДИТ ================= */
function добавитьМесяцы(д, n){
  const x = new Date(НОЛЬ + д * ДЕНЬ), y = x.getUTCFullYear(), m = x.getUTCMonth() + n, день = x.getUTCDate();
  const последний = new Date(Date.UTC(y, m + 1, 0)).getUTCDate();
  return Math.round((Date.UTC(y, m, Math.min(день, последний)) - НОЛЬ) / ДЕНЬ);
}
/* График считаем и здесь: чтобы знать, сколько строк, и проверить итог формул. */
function график(о){
  const r = о.ставка / 100 / 12, out = [];
  let остаток = о.сумма, k = 0;
  const плт = (n, s) => r ? s * r / (1 - Math.pow(1 + r, -n)) : s / n;
  const округл = x => Math.round(x * 100) / 100;
  const постоянный = округл(плт(о.срок, о.сумма)), одПостоянный = округл(о.сумма / о.срок);
  while(остаток > 0.004 && k < о.срок + 600){
    k++;
    const д = добавитьМесяцы(о.первый, k - 1);
    const проценты = округл(остаток * r);
    let од;
    const осталосьМес = о.срок - k + 1;
    if(о.вид === 'аннуитетный'){
      let платёж = о.уменьшать === 'платёж' ? округл(плт(Math.max(1, осталосьМес), остаток)) : постоянный;
      if(осталосьМес <= 1 && о.уменьшать === 'платёж') платёж = округл(остаток + проценты);
      платёж = Math.min(платёж, округл(остаток + проценты));
      од = округл(платёж - проценты);
    } else {
      од = о.уменьшать === 'платёж' ? округл(остаток / Math.max(1, осталосьМес)) : Math.min(одПостоянный, остаток);
      if(осталосьМес <= 1) од = остаток;
      од = Math.min(од, остаток);
    }
    остаток = округл(остаток - од);
    const досрочно = Math.min(остаток, о.досрочные.filter(x => x.д > (k > 1 ? добавитьМесяцы(о.первый, k - 2) : -1e9) && x.д <= д).reduce((s, x) => s + x.сумма, 0));
    остаток = округл(остаток - досрочно);
    out.push({k, д, проценты, од, досрочно, остаток});
  }
  return out;
}
