async function Вклад(){
  const п = параметры({});
  const сумма = +п.вСумма, ставка = +п.вСтавка, срок = Math.round(+п.вСрок), открыт = разобратьДату(п.вДата), пополнение = +п.вПополнение || 0;
  const кап = String(п.вКапитализация || 'ежемесячно');
  if(!(сумма > 0) || !(ставка >= 0) || !(срок >= 1) || открыт === null){ панель.сообщение('Укажите сумму, ставку, срок в месяцах и дату открытия.'); return; }
  const шаг = кап === 'ежеквартально' ? 3 : 1;
  const м = await начало(7, 9 + срок + 3);
  if(!м) return;
  const {r, c} = м, К = k => БУКВА(c + k);
  пиши(r, c, 'Вклад: начисление процентов', {b: 1, size: 12});
  пиши(r + 1, c, 'Сумма'); пиши(r + 1, c + 1, сумма, {fmt: ДЕНЬГИ});
  пиши(r + 2, c, 'Ставка, % годовых'); пиши(r + 2, c + 1, ставка);
  пиши(r + 3, c, 'Капитализация'); пиши(r + 3, c + 1, кап);
  пиши(r + 4, c, 'Пополнение в месяц'); пиши(r + 4, c + 1, пополнение, {fmt: ДЕНЬГИ});
  пиши(r + 5, c, 'Проценты — за фактические дни месяца, дней в году 365 или 366. Без учёта НДФЛ.', {i: 1, color: '#5b6b86', size: 9});
  const h = r + 7;
  ['Месяц', 'С', 'По', 'Дней', 'Остаток', 'Проценты', 'Причислено'].forEach((т, k) => пиши(h, c + k, т, ЗАГ));
  /* остаток месяца k: остаток k−1 + пополнение + причисленные проценты прошлого месяца */
  let остаток = сумма, копится = 0, всего = 0;
  for(let k = 1; k <= срок; k++){
    const rr = h + k, n = rr + 1, от = добавитьМесяцы(открыт, k - 1), до = добавитьМесяцы(открыт, k) - 1;
    const A = (j, nn = n) => '$' + К(j) + '$' + nn;      /* абсолютные ссылки — см. пояснение в графике кредита */
    пиши(rr, c, k, ЯЧ); пиши(rr, c + 1, от, Object.assign({fmt: ДАТА}, ЯЧ)); пиши(rr, c + 2, до, Object.assign({fmt: ДАТА}, ЯЧ));
    формула(rr, c + 3, A(2) + '-' + A(1) + '+1', ЯЧ);
    if(k === 1) формула(rr, c + 4, A(1, r + 2), Object.assign({fmt: ДЕНЬГИ}, ЯЧ));
    else формула(rr, c + 4, A(4, n - 1) + '+' + (кап === 'без капитализации' ? '0' : A(6, n - 1)) + '+' + A(1, r + 5), Object.assign({fmt: ДЕНЬГИ}, ЯЧ));
    const дней = днейВГоду(годДня(от));
    формула(rr, c + 5, 'ОКРУГЛ(' + A(4) + '*' + A(1, r + 3) + '/100*' + A(3) + '/' + дней + ';2)', Object.assign({fmt: ДЕНЬГИ}, ЯЧ));
    /* причисляется в конце каждого месяца (или квартала): накопленное за период */
    const конецПериода = k % шаг === 0 || k === срок;
    if(кап === 'без капитализации') пиши(rr, c + 6, 0, Object.assign({fmt: ДЕНЬГИ}, ЯЧ));
    else if(конецПериода) формула(rr, c + 6, 'СУММ(' + A(5, n - ((k - 1) % шаг)) + ':' + A(5) + ')', Object.assign({fmt: ДЕНЬГИ}, ЯЧ));
    else пиши(rr, c + 6, 0, Object.assign({fmt: ДЕНЬГИ}, ЯЧ));
