  }
  const ит = h + срок + 1;
  пиши(ит, c + 4, 'Итого', {b: 1, align: 'right'});
  формула(ит, c + 5, 'СУММ(' + К(5) + (h + 2) + ':' + К(5) + ит + ')', {b: 1, fmt: ДЕНЬГИ});
  пиши(ит + 1, c + 4, 'На счёте в конце', {b: 1, align: 'right'});
  формула(ит + 1, c + 5, К(4) + ит + (кап === 'без капитализации' ? '' : '+' + К(6) + ит), {b: 1, fmt: ДЕНЬГИ});
  [7, 11, 11, 6, 15, 13, 13].forEach((ш, k) => Api.GetActiveSheet().GetRange(ОБЛАСТЬ(0, c + k, 0, c + k)).SetColumnWidth(ш));
  панель.сообщение('Вклад на ' + срок + ' мес.: проценты ' + руб(всего) + (кап === 'без капитализации' ? ' (выплачиваются, не причисляются)' : ', капитализация ' + кап) + '.');
}

