async function НДС(){
  const п = параметры({});
  const ставка = +(String(п.ндсСтавка || '22').match(/\d+/) || [22])[0];
  const выделить = String(п.ндсДействие || '').startsWith('выделить');
  const в = книга.выделение;
  /* выделены числа — считаем формулами в двух столбцах справа */
  if(в && в.область && (в.r2 > в.r1 || в.c2 > в.c1 || typeof (await ячейка(в.r1, в.c1).прочитать()) === 'number')){
    const строки = await диапазон(ОБЛАСТЬ(в.r1 - 1, в.c1 - 1, в.r2 - 1, в.c1 - 1)).прочитать();
    const чисел = строки.filter(р => typeof р[0] === 'number').length;
    if(чисел){
      const c = в.c2;                               /* первый столбец справа от выделения (с нуля) */
      if(!(await областьПуста(в.r1 - 1, c, в.r2 - 1, c + 1))){
        if(!(await диалог.вопрос('Справа от выделения, в ' + ОБЛАСТЬ(в.r1 - 1, c, в.r2 - 1, c + 1) + ', уже что-то есть. Записать поверх?'))) return;
      }
