        if(typeof р[0] !== 'number') return;
        const r = в.r1 - 1 + i, адр = БУКВА(в.c1 - 1) + (r + 1);
        формула(r, c, выделить ? 'ОКРУГЛ(' + адр + '*' + ст + '/(1+' + ст + ');2)' : 'ОКРУГЛ(' + адр + '*' + ст + ';2)', {fmt: ДЕНЬГИ});
        формула(r, c + 1, выделить ? адр + '-' + БУКВА(c) + (r + 1) : адр + '+' + БУКВА(c) + (r + 1), {fmt: ДЕНЬГИ});
      });
      панель.сообщение('НДС ' + ставка + '% ' + (выделить ? 'выделен' : 'начислен') + ' для ' + чисел + ' чисел: в столбце ' + БУКВА(c) + ' — НДС, в ' + БУКВА(c + 1) + ' — ' + (выделить ? 'сумма без НДС' : 'сумма с НДС') + '.');
      return;
    }
  }
  const сумма = +п.ндсСумма;
  if(!(сумма > 0)){ панель.сообщение('Введите сумму или выделите столбец с суммами.'); return; }
  const ндс = выделить ? Math.round(сумма * ставка / (100 + ставка) * 100) / 100 : Math.round(сумма * ставка) / 100;
  панель.список('ндсИтог', выделить ? [['Сумма с НДС', руб(сумма)], ['НДС ' + ставка + '%', руб(ндс)], ['Без НДС', руб(сумма - ндс)]]
    : [['Сумма без НДС', руб(сумма)], ['НДС ' + ставка + '%', руб(ндс)], ['С НДС', руб(сумма + ндс)]]);
  панель.сообщение('НДС ' + ставка + '%: ' + руб(ндс) + '.');
}
